$pdo->exec('CREATE TABLE town_world_state (world_id TEXT PRIMARY KEY,absolute_minute INTEGER,calendar_day INTEGER,weather_code TEXT,weather_started_at TEXT,next_weather_change_at TEXT,revision INTEGER,updated_at TEXT)');
$pdo->exec("INSERT INTO town_world_state VALUES ('main',0,1,'clear','2026-11-18 12:00:00',NULL,1,'2026-11-18 12:00:00')");
$state = ['schema_version' => 1, 'world' => ['world_id' => 'main']];
[$json, $sha] = town_world_snapshot_encode($state);
$insert = $pdo->prepare('INSERT INTO town_world_snapshots VALUES (?,?,?,?,?,?,?,?,?,?,?)');
$insert->execute(['snap0000000000000000000000000001', 'main', 1, 1, 1, 0, 1, $json, $sha, 'worker', '2026-11-18 12:00:00']);
$pdo->exec("INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json) VALUES (1,'main','time_advanced','world:1','{" . '"minutes":10' . "}')");
$pdo->exec("INSERT INTO town_world_event_journal VALUES (1,'main','public_event','{" . '"event_id":1,"event_type":"time_advanced","source_key":"world:1","payload":{"minutes":10}' . "}',1,'public_event:1','2026-11-18 12:01:00')");
$now = new DateTimeImmutable('2026-11-18 12:02:00', new DateTimeZone('UTC'));
$report = town_world_replay_dry_run($pdo, null, 50);
if (!$report['ok'] || $report['writes_applied'] || $report['journal']['event_count'] !== 1) throw new RuntimeException('Valid replay report should pass without writes.');
$event = town_world_event_journal_since($pdo, 'main', 0, 50)['events'][0];
town_world_replay_apply_event($pdo, $event, $now);
$clock = $pdo->query('SELECT absolute_minute,revision FROM town_world_state WHERE world_id=\'main\'')->fetch(PDO::FETCH_ASSOC);
if ((int)$clock['absolute_minute'] !== 10 || (int)$clock['revision'] !== 2) throw new RuntimeException('The time_advanced adapter must update the authoritative clock deterministically.');
$pdo->exec("INSERT INTO town_world_event_journal VALUES (2,'main','public_event','{" . '"event_id":2,"event_type":"npc_task_completed","source_key":"npc:2","payload":{"task_id":"x"}' . "}',1,'public_event:2','2026-11-18 12:03:00')");
$pdo->exec("INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json) VALUES (2,'main','npc_task_completed','npc:2','{" . '"task_id":"x"' . "}')");
$blocked = town_world_replay_dry_run($pdo, null, 50);
if (!$blocked['ok'] || $blocked['replayable'] || count($blocked['replay_blockers']) !== 1) throw new RuntimeException('Unsupported journal event types must block replay without invalidating the report.');
$npc = str_repeat('d', 32); $task = str_repeat('e', 32);
$pdo->prepare('INSERT INTO town_npc_runtime_states VALUES (?,?,?,?,?,?,?,?)')->execute([$npc, 90, 90, 'walk', $task, 'working', 1, '2026-11-18 12:03:00']);
$pdo->prepare('INSERT INTO town_npc_tasks VALUES (?,?,?,?,?)')->execute([$task, $npc, 'running', null, '']);
$pdo->prepare('INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (?,?,?,?,?,?)')->execute([3, 'main', 'npc_task_completed', 'npc:3', '{"task_id":"' . $task . '"}', $npc]);
$pdo->exec("INSERT INTO town_world_event_journal VALUES (3,'main','public_event','{" . '"event_id":3,"event_type":"npc_task_completed","source_key":"npc:3","payload":{"action":"rest","task_status":"completed","task_id":"' . $task . '","tile_x":101,"tile_y":102}' . "}',1,'public_event:3','2026-11-18 12:04:00')");
$event3 = town_world_event_journal_since($pdo, 'main', 2, 50)['events'][0];
town_world_replay_apply_event($pdo, $event3, $now);
$runtime = $pdo->query('SELECT tile_x,tile_y,state,current_task_id FROM town_npc_runtime_states')->fetch(PDO::FETCH_ASSOC);
if ((int)$runtime['tile_x'] !== 101 || (int)$runtime['tile_y'] !== 102 || $runtime['state'] !== 'rest' || $runtime['current_task_id'] !== null) throw new RuntimeException('NPC rest completion adapter must restore the authoritative runtime state.');
$walkTask = str_repeat('f', 32); $pdo->prepare('INSERT INTO town_npc_tasks VALUES (?,?,?,?,?)')->execute([$walkTask, $npc, 'running', null, '']);
$pdo->prepare('INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (?,?,?,?,?,?)')->execute([5, 'main', 'npc_task_completed', 'npc:5', '{"action":"walk","task_status":"completed","task_id":"' . $walkTask . '","tile_x":110,"tile_y":111}', $npc]);
$walkEvent = ['event_type' => 'public_event', 'event_id' => 5, 'source_key' => 'npc:5', 'created_at' => '2026-11-18 12:05:00', 'payload' => ['event_id' => 5, 'event_type' => 'npc_task_completed', 'source_key' => 'npc:5', 'payload' => ['action' => 'walk', 'task_status' => 'completed', 'task_id' => $walkTask, 'tile_x' => 110, 'tile_y' => 111]]];
town_world_replay_apply_event($pdo, $walkEvent, $now);
$runtime = $pdo->query('SELECT tile_x,tile_y,state FROM town_npc_runtime_states')->fetch(PDO::FETCH_ASSOC);
if ((int)$runtime['tile_x'] !== 110 || (int)$runtime['tile_y'] !== 111 || $runtime['state'] !== 'rest') throw new RuntimeException('NPC walk completion adapter must restore the final position.');
$workCompletionTask = str_repeat('2', 32);
$pdo->prepare('INSERT INTO town_npc_tasks VALUES (?,?,?,?,?)')->execute([$workCompletionTask, $npc, 'running', null, '']);
$pdo->prepare('UPDATE town_npc_runtime_states SET state=\'work\',current_task_id=:task WHERE npc_id=:npc')->execute([':task' => $workCompletionTask, ':npc' => $npc]);
$workCompletionEvent = ['event_type' => 'public_event', 'event_id' => 7, 'source_key' => 'npc:7', 'created_at' => '2026-11-18 12:05:30', 'payload' => ['event_id' => 7, 'event_type' => 'npc_task_completed', 'source_key' => 'npc:7', 'payload' => ['action' => 'work', 'task_status' => 'completed', 'task_id' => $workCompletionTask, 'tile_x' => 120, 'tile_y' => 121]]];
$pdo->prepare('INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (?,?,?,?,?,?)')->execute([7, 'main', 'npc_task_completed', 'npc:7', '{"action":"work","task_status":"completed","task_id":"' . $workCompletionTask . '","tile_x":120,"tile_y":121}', $npc]);
town_world_replay_apply_event($pdo, $workCompletionEvent, $now);
$runtime = $pdo->query('SELECT tile_x,tile_y,state,current_task_id FROM town_npc_runtime_states')->fetch(PDO::FETCH_ASSOC);
if ((int)$runtime['tile_x'] !== 120 || (int)$runtime['tile_y'] !== 121 || $runtime['state'] !== 'rest' || $runtime['current_task_id'] !== null) throw new RuntimeException('NPC work completion adapter must restore the final position without applying a work effect.');
$failedTask = str_repeat('1', 32); $pdo->prepare('INSERT INTO town_npc_tasks VALUES (?,?,?,?,?)')->execute([$failedTask, $npc, 'running', null, '']);
$pdo->prepare('UPDATE town_npc_runtime_states SET state=\'work\',current_task_id=:task WHERE npc_id=:npc')->execute([':task' => $failedTask, ':npc' => $npc]);
$failedEvent = ['event_type' => 'public_event', 'event_id' => 6, 'source_key' => 'npc:6', 'created_at' => '2026-11-18 12:06:00', 'payload' => ['event_id' => 6, 'event_type' => 'npc_task_failed', 'source_key' => 'npc:6', 'payload' => ['task_id' => $failedTask, 'failure_reason' => 'blocked']]];
$pdo->prepare('INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (?,?,?,?,?,?)')->execute([6, 'main', 'npc_task_failed', 'npc:6', '{"task_id":"' . $failedTask . '","failure_reason":"blocked"}', $npc]);
town_world_replay_apply_event($pdo, $failedEvent, $now);
$failedRow = $pdo->query('SELECT status,failure_reason FROM town_npc_tasks WHERE task_id=\'' . $failedTask . '\'')->fetch(PDO::FETCH_ASSOC);
if ($failedRow['status'] !== 'failed' || $failedRow['failure_reason'] !== 'blocked') throw new RuntimeException('NPC task failure adapter must restore failure state.');
$pdo->exec('CREATE TABLE town_work_points (point_id TEXT PRIMARY KEY,world_id TEXT,point_key TEXT,name TEXT,kind TEXT,tile_x INTEGER,tile_y INTEGER,interaction_json TEXT,result_json TEXT,enabled INTEGER,created_at TEXT,updated_at TEXT)');
$pdo->exec('CREATE TABLE town_farm_plots (plot_id TEXT PRIMARY KEY,world_id TEXT,point_id TEXT,plot_key TEXT,name TEXT,crop_id TEXT,growth_stage INTEGER,state TEXT,watered_at TEXT,watering_count INTEGER,enabled INTEGER,created_at TEXT,updated_at TEXT)');
$pdo->exec('CREATE TABLE town_work_runs (run_id TEXT PRIMARY KEY,point_id TEXT,npc_id TEXT,task_id TEXT,job TEXT,status TEXT,result_json TEXT,started_at TEXT,completed_at TEXT)');
$pointId = str_repeat('a', 32); $workRunId = str_repeat('b', 32); $workTaskId = str_repeat('c', 32); $workNpcId = str_repeat('d', 32);
$pdo->prepare('INSERT INTO town_work_points VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$pointId, 'main', 'farm-zone-3', '三号农田', 'farm', 90, 90, '{}', '{"effect":"water_crop"}', 1, '2026-11-18 12:00:00', '2026-11-18 12:00:00']);
$pdo->prepare('INSERT INTO town_farm_plots VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([str_repeat('e', 32), 'main', $pointId, 'farm-plot-3-1', '一号地块', 'wheat', 1, 'growing', null, 0, 1, '2026-11-18 12:00:00', '2026-11-18 12:00:00']);
$pdo->prepare('INSERT INTO town_world_events (event_id,world_id,event_type,source_key,public_payload_json,actor_npc_id) VALUES (?,?,?,?,?,?)')->execute([4, 'main', 'npc_task_replay_delta', 'npc:4', json_encode(['task_id' => $workTaskId, 'action' => 'work', 'job' => 'water_crop', 'work_run_id' => $workRunId, 'work_point' => ['point_id' => $pointId, 'point_key' => 'farm-zone-3', 'kind' => 'farm'], 'work_result' => ['income' => 0, 'world_effect' => ['effect' => 'water_crop', 'applied' => true]]], JSON_UNESCAPED_UNICODE), $workNpcId]);
$pdo->exec("INSERT INTO town_world_event_journal VALUES (4,'main','public_event','{" . '"event_id":4,"event_type":"npc_task_replay_delta","source_key":"npc:4","payload":{"task_id":"' . $workTaskId . '","action":"work","job":"water_crop","work_run_id":"' . $workRunId . '","work_point":{"point_id":"' . $pointId . '","point_key":"farm-zone-3","kind":"farm"},"work_result":{"income":0,"world_effect":{"effect":"water_crop","applied":true}}}' . "}',1,'public_event:4','2026-11-18 12:05:00')");
$workEvent = town_world_event_journal_since($pdo, 'main', 3, 50)['events'][0];
town_world_replay_apply_event($pdo, $workEvent, $now);
$plot = $pdo->query('SELECT state,watering_count FROM town_farm_plots')->fetch(PDO::FETCH_ASSOC);
if ($plot['state'] !== 'watered' || (int)$plot['watering_count'] !== 1 || (int)$pdo->query('SELECT COUNT(*) FROM town_work_runs')->fetchColumn() !== 1) throw new RuntimeException('Work replay must apply a farm effect and write one work run.');
town_world_replay_apply_event($pdo, $workEvent, $now);
if ((int)$pdo->query('SELECT watering_count FROM town_farm_plots')->fetchColumn() !== 1 || (int)$pdo->query('SELECT COUNT(*) FROM town_work_runs')->fetchColumn() !== 1) throw new RuntimeException('Work replay must be idempotent by work_run_id.');
$pdo->exec("UPDATE town_world_snapshots SET state_sha256='bad' WHERE snapshot_id='snap0000000000000000000000000001'");
$invalid = town_world_replay_dry_run($pdo, null, 50);
if ($invalid['ok'] || $invalid['writes_applied'] === true || ($invalid['errors'][0]['code'] ?? '') !== 'snapshot_invalid') throw new RuntimeException('Corrupt snapshots must fail closed in dry-run.');
echo "town_world_replay_test: checks ok\n";
